1	<!doctype html>
2	<html><head><meta charset="utf-8"><title>Screen 05 tunnel kit game test</title>
3	<meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no">
4	<style>
5	html,body{margin:0;background:#000;overflow:hidden;font-family:system-ui,sans-serif}canvas{display:block}
6	#hud{position:fixed;left:0;right:0;top:10px;display:flex;flex-direction:column;align-items:center;gap:8px;pointer-events:none}
7	.bar{display:flex;gap:28px;align-items:center;background:linear-gradient(#7b2bbf,#4a1386);border:2px solid #d9a7ff;border-radius:30px;padding:6px 22px;color:#fff;font-weight:800;font-size:22px;box-shadow:0 2px 8px #0006}
8	.title{background:#5a1aa0e0;border:2px solid #f2c14e;border-radius:20px;padding:4px 18px;color:#fff;font-weight:800;font-style:italic;font-size:17px;letter-spacing:.5px}
9	</style>
10	<script type="importmap">{"imports":{"three":"./node_modules/three/build/three.module.js","three/addons/":"./node_modules/three/examples/jsm/"}}</script>
11	</head><body>
12	<div id="hud"><div class="bar"><span>&#10084;&#65039; 5/5</span><span id="coins">&#129689; 1,420</span></div><div class="title">05 &middot; FLOW INTO THE CURRENT</div></div>
13	<script type="module">
14	// Round 33 KIT TEST (experimental, not the game): a real 3D tunnel kit fitted to the approved Screen 05 painting
15	// (tools/kit05/kit_model.py) and textured with the painting's own pixels (bake_kit.py). Every scenery vertex goes through the same
16	// camera-relative depth curve as the bake (identity up to ring 2, then the painting's constant ring ratio), so the far tunnel keeps
17	// the painted perspective from every camera position while Benny swims. Benny = the round-32 Benny (mesh, bake, paddling shader).
18	import * as THREE from 'three';
19	import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
20	import { installControls } from './controls.js'; // round-32 swipe controls, unchanged
21	const q = new URLSearchParams(location.search);
22	// round 37 (2026-11-21): the user's THREE buildable options, same camera, Benny, controls, coins and reference-video movement (?move=1):
23	//   ?opt=a  MAXIMUM ARTWORK FIDELITY  = the approved picture's own pixels on the 3D tunnel AND the river (round-35 painted river)
24	//   ?opt=b  NATURAL 3D WATER          = the approved picture's own pixels on the tunnel; the river redrawn live (w37=1): flow-aligned
25	//                                       cyan ribbons, magenta bands, star sparkles, foam domes, measured from the painting, sharp at any distance
26	//   ?opt=c  ARCADE / GAME-READY       = everything redrawn clean (clean37=1: walls, gold rings, 3D gold paddles) + the simpler river (w37=2)
27	// No ?opt = the round-36 default, unchanged.
28	const OPT = (q.get('opt') ?? '').toLowerCase();
29	for (const [k, v] of ({ a: [['ownoff', '1'], ['move', '1']], b: [['ownoff', '1'], ['move', '1'], ['w37', '1']],
30	  c: [['ownoff', '1'], ['move', '1'], ['w37', '2'], ['clean37', '1']] })[OPT] ?? []) if (!q.has(k)) q.set(k, v);
31	const W37 = +(q.get('w37') ?? 0), CLEAN37 = q.get('clean37') === '1';
32	const W = +(q.get('w') ?? 412), H = +(q.get('h') ?? 915);
33	const renderer = new THREE.WebGLRenderer({ antialias: true, preserveDrawingBuffer: true });
34	renderer.setPixelRatio(1); renderer.setSize(W, H); document.body.appendChild(renderer.domElement);
35	const K = await (await fetch('kit.json')).json();
36	// round 36 TEST ?proj=1 = PURE camera-matched projection: every scenery texel stays the APPROVED picture's own pixel projected onto the fitted
37	// 3D tunnel / water at its world place (no hand-over to the sharper repeating sections, no foam domes / bubbles), and the camera never rotates
38	// (no yaw / roll: the painted vanishing point stays where the painting has it; it only translates with Benny's river path and lanes)
39	const PROJ = q.get('proj') === '1';
40	if (PROJ) for (const [k, v] of [['pfade', '-2,-1,-2,-1'], ['p_yawmax', '0'], ['p_rollmax', '0']]) if (!q.has(k)) q.set(k, v);
41	const OWNFADE = PROJ ? [-2, -1] : (K.own?.fade ?? [0.42, 0.62]);
42	// round 36c ?move=1: the user's reference-video swimming. Benny really travels across the screen on lane changes (the camera follows only
43	// 35 % of his lane offset, the on-screen guard is wider), leans more into each change; swimfx adds the foam collar, bubble trails and rings
44	const MOVE = q.get('move') === '1';
45	if (MOVE) for (const [k, v] of [['p_camk', '0.35'], ['p_gneg', '0.10'], ['p_gpos', '0.13'], ['c_BANK_K', '0.3']]) if (!q.has(k)) q.set(k, v);
46	const V3 = (a) => new THREE.Vector3(...a);
47	const A = V3(K.A), NUP = V3(K.NUP), RR = V3(K.RR), A0 = V3(K.A0);
48	const ringT = (k) => K.Z2 + (k - 2) * K.S;
49	const scene = new THREE.Scene(); scene.background = new THREE.Color(0x120418);
50	const camera = new THREE.PerspectiveCamera(K.fov, W / H, 0.02, 400);
51	const camQ0 = new THREE.Quaternion().setFromRotationMatrix(new THREE.Matrix4().lookAt(new THREE.Vector3(), V3(K.cam_fwd), V3(K.cam_up)));
52	
53	// ---- the depth curve (same as kit_model.g / remap) ----
54	const REMAP = { uCam: { value: new THREE.Vector3() }, uAx: { value: A.clone() }, uZ2: { value: K.Z2 }, uBias: { value: +(q.get('kbias') ?? -0.7) }, uOwnOff: { value: 0 } };
55	// round 36b ?ownoff=1: once Benny has swum ~1-2 u, every wall / ring section uses the shared painted section (the start view's own pixels of FAR
56	// sections no longer line up with the tunnel seen from further on: they showed a doubled 'ghost' set of rings near the core)
57	const OWNOFF = q.get('ownoff') === '1' || (q.get('r36') === '1' && q.get('ownoff') !== '0');
58	const REMAP_GLSL = `uniform vec3 uCam; uniform vec3 uAx; uniform float uZ2;
59	vec3 kitRemap(vec3 wp){ vec3 d = wp - uCam; float za = dot(d, uAx); float gz = za <= uZ2 ? za : uZ2 * exp((za - uZ2) / uZ2); return wp + (gz - za) * uAx; }`;
60	const kitMat = (map, extra = {}, own = null) => {   // own = { tex, vr: [v0, v1] }: this section's OWN painted pixels (atlas rows)
61	  const m = new THREE.MeshBasicMaterial({ map, toneMapped: false, side: THREE.DoubleSide, ...extra });
62	  m.customProgramCacheKey = () => (own ? 'kit-own' : 'kit');   // three.js keys programs on the onBeforeCompile source: identical for both variants
63	  const OU = own ? { uOwn: { value: own.tex }, uVr: { value: new THREE.Vector2(...own.vr) }, uFade: { value: new THREE.Vector2(...OWNFADE) } } : {};
64	  m.onBeforeCompile = (sh) => {
65	    Object.assign(sh.uniforms, REMAP, OU);
66	    sh.vertexShader = sh.vertexShader.replace('#include <common>', '#include <common>\n' + REMAP_GLSL + '\nvarying float vKitT; varying float vKitD;')
67	      .replace('#include <project_vertex>', `vec4 kwp = modelMatrix * vec4(transformed, 1.0); vKitT = dot(kwp.xyz, uAx); vKitD = dot(kwp.xyz - uCam, uAx); kwp.xyz = kitRemap(kwp.xyz);
68	        vec4 mvPosition = viewMatrix * kwp; gl_Position = projectionMatrix * mvPosition;`);
69	    sh.fragmentShader = sh.fragmentShader.replace('#include <common>', '#include <common>\nuniform float uBias;' + (own ? '\nuniform sampler2D uOwn; uniform vec2 uVr; uniform vec2 uFade; uniform float uOwnOff; varying float vKitT; varying float vKitD;' : ''));
70	    if (!own) sh.fragmentShader = sh.fragmentShader.replace('#include <map_fragment>', 'diffuseColor *= texture(map, vMapUv, uBias);');
71	    if (own) sh.fragmentShader = sh.fragmentShader
72	      .replace('#include <map_fragment>', `vec4 kTile = texture(map, vMapUv, uBias);
73	        vec4 kOwn = texture(uOwn, vec2(vMapUv.x, 1.0 - (uVr.x + (1.0 - vMapUv.y) * (uVr.y - uVr.x))), uBias);
74	        float kF = smoothstep(uFade.x, uFade.y, vKitD / max(vKitT, 1e-3)) * (1.0 - uOwnOff);   // 1 at the painted distance (start), 0 once Benny is close
75	        diffuseColor *= mix(kTile, kOwn, kF);`);
76	  };
77	  return m;
78	};
79	const tl = new THREE.TextureLoader();
80	const tex = async (f, rep = false) => { const t = await tl.loadAsync(f); t.colorSpace = THREE.SRGBColorSpace; t.anisotropy = 8; if (rep) t.wrapS = THREE.RepeatWrapping; return t; };
81	const [wallTex, ringTex, riverTex, wallOwn, ringOwn] = await Promise.all([tex('wall.png'), tex('ring.png'), tex('river.png'), tex('wall_own.png'), tex('ring_own.png')]);
82	// round 35 (lead): the river = the user's OWN painted river (isolated water art, colour-matched) in its world place, repeated every 3 ring
83	// sections (bake_river35.py: prefix t_pre..ta + one period P, sharp painted streak detail added where the painting is softer). ?r35=0 = round-34 ribbon
84	const R35 = K.river35 && q.get('r35') !== '0' ? K.river35 : null;
85	const PUFFS = !!K.river35 && q.get('puffs') !== '0';   // round 35: painted foam domes + bubbles (see below)
86	// round 36b TEST ?r36=1: the river = the painting's own SHARP near water laid along every bend (bake_river36.py), river-local (u = lateral
87	// from the river core, v = along the river), periodic with the core; no added streak layer (it is already the sharp painted water)
88	const R36 = K.river36 && q.get('r36') === '1' ? K.river36 : null;
89	// the round-34 ribbon textures are only loaded when the round-34 river is asked for (?r35=0): 4 MB less to download / hold on a phone
90	const tex1 = () => { const t = new THREE.DataTexture(new Uint8Array([0, 0, 0, 255]), 1, 1); t.needsUpdate = true; return t; };
91	const riverTile = R35 ? tex1() : await tex('river_tile.png'); riverTile.wrapT = THREE.RepeatWrapping;
92	const riverPink = R35 ? tex1() : await tex(K.river_tile?.ribbon ? 'river_pink.png' : 'river_tile.png'); riverPink.wrapT = THREE.RepeatWrapping;   // round 34: pink edge-band version of the ribbon
93	const river35Tex = R35 ? await tex('river35.png') : riverTile;
94	const river36Tex = R36 ? await tex('river36.png') : river35Tex;
95	// sharp painted streaks (luminance detail, river-local), added live near the camera where the painted row is soft, streaming with the current
96	const r35Det = R35?.detail ? await tl.loadAsync('river35_detail.png') : riverTile;
97	if (R35?.detail) { r35Det.colorSpace = THREE.NoColorSpace; r35Det.wrapS = THREE.MirroredRepeatWrapping; r35Det.wrapT = THREE.RepeatWrapping; r35Det.anisotropy = 8; }
98	const ownOf = (kind, atlas, k) => { const r = K.own?.[kind]?.rows?.[k]; return r && !q.get('noown') ? { tex: atlas, vr: [r[0] / K.own[kind].h, r[1] / K.own[kind].h] } : null; };
99	const wallMat = kitMat(wallTex), ringMat = kitMat(ringTex);
100	// ---- round 34 (S1): WORLD-ANCHORED winding river. The river centre c(t) (kit.json river_center_axis, measured on the painting's coin
101	// trail + cyan channel, continued with varied S-bends) bends the flowing ribbon tile (river-local u = lateral - c(t)); Benny's path
102	// follows the same line (kit.json river_center, S3). At the start the water is the PAINTED water at its own world place (exact approved
103	// picture at frame 0); each painted texel cross-fades to the ribbon as the camera approaches it (sooner for far, low-resolution texels).
104	const RC = K.river_center_axis ?? { t0: 0, dt: 1, c: [0, 0] };
105	const centerTex = new THREE.DataTexture(new Float32Array(RC.c), RC.c.length, 1, THREE.RedFormat, THREE.FloatType); centerTex.needsUpdate = true;
106	const riverC = (t) => { const x = Math.min(Math.max((t - RC.t0) / RC.dt, 0), RC.c.length - 1.001), i = Math.floor(x), f = x - i; return RC.c[i] + (RC.c[i + 1] - RC.c[i]) * f; };   // axis lateral of the centre at axial t
107	window.riverC = riverC;
108	const FLOW = { uFlowOn: { value: 0 }, uFlowL: { value: +(q.get('flowl') ?? 0.10) }, uWT: { value: new THREE.Vector3(K.water.T0, Math.log(K.water.T1 / K.water.T0), 0) }, uFoam: { value: null }, uHWD: { value: K.water.HWD },
109	  uFlow: { value: 0 }, uRT: { value: new THREE.Vector3(K.river_tile.t0, K.river_tile.L, K.river_tile.RU ?? 1.05) }, uRiverTile: { value: riverTile }, uRiverPink: { value: riverPink },
110	  uCenter: { value: centerTex }, uCN: { value: new THREE.Vector3(RC.t0, RC.dt, RC.c.length) },
111	  uPF: { value: new THREE.Vector4(...(q.get('pfade') ?? '0.45,0.65,0.85,0.97').split(',').map(Number)) },   // painted -> ribbon fade (ratio now/start distance): near texels, far texels
112	  uEdge: { value: new THREE.Vector4(...(q.get('redge') ?? '0.80,0.60,5.0,13.0').split(',').map(Number)) },
113	  uR35On: { value: R35 ? 1 : 0 }, uR35: { value: river35Tex }, uR35A: { value: new THREE.Vector4(R35?.t_pre ?? 0, R35?.ta ?? 1, R35?.P ?? 1, R35 ? R35.n_pre / (R35.n_pre + R35.n_per) : 0) }, uR35B: { value: +(q.get('r35bias') ?? 0.0) },
114	  uR35Det: { value: r35Det }, uR35D: { value: new THREE.Vector4(R35?.detail?.L ?? 1, R35?.detail?.c0 ?? 0, +(q.get('detflow') ?? 1.0), R35?.detail ? +(q.get('detgain') ?? 1.3) : 0) }, uR35DS: { value: new THREE.Vector4(...(q.get('detshape') ?? '5,1,3,8').split(',').map(Number)) },
115	  uProjDet: { value: PROJ && R35?.detail ? +(q.get('projdet') ?? 1.0) : 0 },
116	  uR36On: { value: R36 ? 1 : 0 }, uR36: { value: river36Tex }, uR36A: { value: new THREE.Vector4(R36?.ta ?? 0, R36?.P ?? 1, R36?.umax ?? 1, +(q.get('r36flow') ?? 0.25)) },
117	  uR35P: { value: new THREE.Vector3(...(q.get('pinkband') ?? '0,0.44,0.56').split(',').map(Number)) },   // ribbon foam edge |u| near, far factor, far range
118	  // round 37 (?w37=1 option B / 2 option C): the river DRAWN LIVE in river space; x = river half-width (world u), y = flow speed toward the camera
119	  uW37: { value: W37 }, uW37A: { value: new THREE.Vector4(+(q.get('w37rw') ?? 0.6), +(q.get('w37flow') ?? 1.0), +(q.get('w37ck') ?? 1.2), 0) }, uW37T: { value: 0 } };
120	const riverMat = (() => { const m = kitMat(riverTex); const base = m.onBeforeCompile; m.customProgramCacheKey = () => 'kit-river34';
121	  m.onBeforeCompile = (sh) => { base(sh); Object.assign(sh.uniforms, FLOW);
122	    sh.fragmentShader = sh.fragmentShader.replace('uniform float uBias;', `uniform float uBias; uniform float uFlow; uniform vec3 uRT; uniform sampler2D uRiverTile; uniform sampler2D uFoam; uniform float uHWD; uniform vec3 uWT; uniform float uFlowL; uniform float uFlowOn; varying float vKitT; varying float vKitD;
123	      uniform sampler2D uRiverPink; uniform sampler2D uCenter; uniform vec3 uCN; uniform vec4 uPF; uniform vec4 uEdge;
124	      uniform float uR35On; uniform sampler2D uR35; uniform vec4 uR35A; uniform float uR35B; uniform sampler2D uR35Det; uniform vec4 uR35D; uniform vec4 uR35DS; uniform vec3 uR35P; uniform float uProjDet; uniform float uR36On; uniform sampler2D uR36; uniform vec4 uR36A;
125	      vec4 r36(float u, float t){ float r = (t - uR36A.x) / uR36A.y; vec2 uv = vec2((u + uR36A.z) / (2.0 * uR36A.z), r);
126	        return textureGrad(uR36, vec2(uv.x, fract(uv.y)), dFdx(uv), dFdy(uv)); }
127	      // round 35: painted river texel at world axial t (continuous row coordinate: prefix rows, then the period repeats)
128	      float r35Row(float t){ return t < uR35A.y ? uR35A.w * clamp((t - uR35A.x) / (uR35A.y - uR35A.x), 0.0, 1.0) : uR35A.w + (1.0 - uR35A.w) * (t - uR35A.y) / uR35A.z; }
129	      vec4 r35(float x, float t){ float r = r35Row(t); float rw = r >= 1.0 ? uR35A.w + mod(r - uR35A.w, 1.0 - uR35A.w) : r;
130	        vec2 gx = vec2(dFdx(x), dFdx(r)) * exp2(uR35B), gy = vec2(dFdy(x), dFdy(r)) * exp2(uR35B);
131	        return textureGrad(uR35, vec2(x, rw), gx, gy); }
132	      float kCenter(float t){ float x = clamp((t - uCN.x) / uCN.y, 0.0, uCN.z - 1.001); int i = int(floor(x)); return mix(texelFetch(uCenter, ivec2(i, 0), 0).r, texelFetch(uCenter, ivec2(i + 1, 0), 0).r, fract(x)); }
133	      // ---- round 37: the approved water design drawn live (no bitmap -> sharp at every distance, flows naturally) ----
134	      // colours = the user's isolated water art, measured (near half, by luminance): blue 5/50/95 % = (1,124,234) (0,164,251) (57,238,252),
135	      // pink = (164,43,212) (251,34,217) (252,134,251); shares blue 83 % / pink 18 % / white 4 %
136	      uniform float uW37; uniform vec4 uW37A; uniform float uW37T;
137	      vec3 w37c(float r, float g, float b){ return pow(vec3(r, g, b) / 255.0, vec3(2.2)); }
138	      float w37h(vec2 p){ vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }
139	      float w37n(vec2 p){ vec2 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f);
140	        return mix(mix(w37h(i), w37h(i + vec2(1.0, 0.0)), f.x), mix(w37h(i + vec2(0.0, 1.0)), w37h(i + vec2(1.0, 1.0)), f.x), f.y); }
141	      vec4 w37(float kT, float kLat, float kZ){
142	        float simple = step(1.5, uW37), RW = uW37A.x;
143	        float cK = uW37A.z;                                                 // the painted S swings wider than Benny's safe swimming line
144	        float cs = (kCenter(kT + 0.05) - kCenter(kT - 0.05)) * 10.0 * cK;
145	        float kU = (kLat - cK * kCenter(kT)) / sqrt(1.0 + cs * cs);              // distance across the river from its winding centre line
146	        float u = kU / RW, au = abs(u);
147	        float tp = kT + uW37T * uW37A.y;                                    // the design streams toward the camera with the current
148	        // ---- silk ribbons along the flow (each: deep blue edge -> bright cyan crest + thin highlight, then a crisp step to the next)
149	        float NR = mix(9.0, 3.5, simple);   // round 38: finer silk ribbons (approved water has ~2x the fine streak texture)
150	        float mea = 0.55 * sin(tp * 0.83 + u * 2.3) + 0.35 * sin(tp * 1.71 - u * 3.1 + 1.3) + 0.7 * (w37n(vec2(u * 1.6, tp * 0.45)) - 0.5);
151	        float w = u * NR * 0.5 + mea * mix(1.0, 0.35, simple);
152	        float f = fract(w), fw = max(fwidth(w), 1e-4);
153	        float lod = 1.0 - smoothstep(0.15, 0.5, fw);                         // ribbons thinner than ~3 px fade to their average (no grain)
154	        float dropW = max(0.06, 1.5 * fw);
155	        // mostly bright glossy cyan; a thin dark groove where one ribbon tucks under the next, the crest just before it
156	        float sh = 0.2 + 0.5 * pow(smoothstep(0.0, 0.92, f), 2.2) - 0.3 * (1.0 - smoothstep(0.0, max(0.14, 2.0 * fw), f)) * smoothstep(0.0, 0.5 * dropW, f) - 0.36 * smoothstep(1.0 - dropW, 1.0, f);
157	        sh = mix(0.38, clamp(sh, 0.0, 1.0), lod);
158	        float crest = exp(-pow((f - 0.86) / max(0.045, fw * 1.2), 2.0)) * lod * smoothstep(0.15, 0.6, w37n(vec2(floor(w) * 7.13, tp * 1.4)));
159	        // near the camera the painting shows broad arcs across the flow (option B only)
160	        float near = (1.0 - smoothstep(0.9, 2.6, kZ)) * (1.0 - simple);
161	        float arcv = sin(6.2832 * (tp * 1.15 + 0.45 * u * u));
162	        sh = clamp(sh + 0.26 * near * arcv, 0.0, 1.0);
163	        // fine brushed striations along the flow (low contrast, gone where they would be thinner than a pixel)
164	        { float X = kU * 95.0 + 2.0 * w37n(vec2(kU * 9.0, tp * 1.1)); float fl = 1.0 - smoothstep(0.25, 0.6, fwidth(X));
165	          sh = clamp(sh + 0.12 * fl * (1.0 - simple) * sin(X), 0.0, 1.0); }
166	        vec3 bD = w37c(4.0, 100.0, 228.0), bM = w37c(10.0, 150.0, 248.0), bB = w37c(90.0, 225.0, 255.0);   // round 38: measured approved water mean (48,163,239), sat 0.82
167	        vec3 pD = w37c(164.0, 43.0, 212.0), pM = w37c(251.0, 34.0, 217.0), pB = w37c(252.0, 134.0, 251.0);
168	        vec3 blue = sh < 0.55 ? mix(bD, bM, sh / 0.55) : mix(bM, bB, (sh - 0.55) / 0.45);
169	        vec3 pink = sh < 0.55 ? mix(pD, pM, sh / 0.55) : mix(pM, pB, (sh - 0.55) / 0.45);
170	        // magenta bands between the cyan core and the foam on both sides (wandering a little, wider on the outside of each bend)
171	        float bend = clamp((kCenter(kT + 0.3) - kCenter(kT - 0.3)) * 2.0 * cK, -1.0, 1.0);
172	        float pin = 0.52 + 0.06 * sin(tp * 0.71 + sign(u) * 1.7) - 0.08 * bend * sign(u) + 0.04 * (w37n(vec2(tp * 0.9, sign(u) * 5.0)) - 0.5);
173	        float pkE = max(0.03, 1.5 * fwidth(u));
174	        float pk = smoothstep(pin - pkE, pin + pkE, au) * (1.0 - smoothstep(0.9 - pkE, 0.9 + pkE, au));
175	        pk *= mix(1.0, 0.85, simple);
176	        vec3 col = mix(blue, pink, pk);
177	        col = mix(col, mix(vec3(0.85, 0.97, 1.0), vec3(1.0, 0.8, 0.97), pk), crest * 0.7);
178	        // white highlight streaks riding the current (the painting's bright dashes along every ribbon), two scales; thin far ones
179	        // fade to a gentle brightening instead of flickering
180	        for (int L = 0; L < 3; L++) { float cw = L == 0 ? 0.05 : (L == 1 ? 0.11 : 0.026), rl = L == 0 ? 0.32 : (L == 1 ? 0.6 : 0.16);
