19	<script type="module">
20	// ======================================================================================================================================
21	// Rainbow SCREEN KIT game page (round 43) - one page for every playable screen built with tools/screenkit: the screen's own fitted
22	// layout (layout.json, from screens/NN/fitNN.py) + its Blender scenery (scene.glb, tools/screenkit/blender_kit.py). At load, the screen's
23	// approved picture(s) are BAKED once onto the meshes from the camera(s) fitted to them (depth-tested, masked where the game draws Benny /
24	// coins / HUD / bubbles itself, clean plate inside the masks), exactly the proven Bubble Dash method (tools/reflock/section.html, which
25	// stays untouched). Plain perspective camera; nothing follows the camera; no projection, no picture planes, no screen overlays.
26	// Shared game code: Benny 31 (paddling shader), tools/kit05/controls.js swipes, swimfx.js, the coin / splash textures.
27	// Screen-specific values come ONLY from layout.json.
28	// ======================================================================================================================================
29	import * as THREE from 'three';
30	import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
31	import { installControls } from './controls.js';
32	import { bake as bakeAll, famOf, tplOnly, exportBake, exportTemplates, loadTemplates, applyTemplates, foamFromPicture } from './bake.js';   // r45: bake + artwork-sampled materials
33	import { installQA } from './qa.js';   // r45: QA views for the automated preview check (repeated picture camera, surface ID pass)
34	const q = new URLSearchParams(location.search);
35	const LAY = await (await fetch('layout.json')).json();
36	for (const [k, v] of [['c_LANE', String(LAY.lane ?? 0.3)], ['c_LAT_MAX', String((LAY.lane ?? 0.3) * 1.2)], ['speed', String(LAY.speed ?? 2.2)]]) if (!q.has(k)) q.set(k, v);
37	const W = +(q.get('w') ?? innerWidth), H = +(q.get('h') ?? innerHeight);
38	const renderer = new THREE.WebGLRenderer({ antialias: true, preserveDrawingBuffer: true });
39	renderer.setPixelRatio(q.get('w') ? 1 : Math.min(2, devicePixelRatio)); renderer.setSize(W, H); document.body.appendChild(renderer.domElement);
40	const V3 = (a) => new THREE.Vector3(a[0], a[1], a[2]);
41	const scene = new THREE.Scene(); scene.background = new THREE.Color(q.get('sentinel') ? 0x00ff00 : 0x1a0630);   // ?sentinel=1: holes show pure green
42	const camera = new THREE.PerspectiveCamera(LAY.fov, W / H, 0.03, 300); camera.rotation.order = 'YXZ';
43	const world = new THREE.Group(); world.name = 'world'; scene.add(world);
44	const lerp = (a, b, x) => a + (b - a) * x, sstep = (a, b, x) => { const k = Math.min(1, Math.max(0, (x - a) / (b - a))); return k * k * (3 - 2 * k); };
